#!/bin/bash
set -euo pipefail
name=''; uuid=''
while getopts ':i:n:s:' opt; do case "$opt" in i) uuid="$OPTARG";; n|s) name="$OPTARG";; *) exit 64;; esac; done
[[ "$(id -un)" == 'emprendeclaro' && "$name" == 'emprendeclaro_polish_v3' ]] || exit 77
umask 077
/usr/local/bin/python3.11 - "$uuid" <<'PYCODE'
import pathlib,os,stat,sys,re,json,gzip,base64,hashlib,time,tempfile,urllib.request
root=pathlib.Path('/home/emprendeclaro/apps/emprendeclaro_demo_v2')
run=pathlib.Path('/home/emprendeclaro/apps/emprendeclaro_polish_v3')
assert pathlib.Path.cwd()==run and root.resolve()==root and root.stat().st_uid==os.getuid()
raw=base64.b64decode('');assert hashlib.sha256(raw).hexdigest()=='cce37ada2e6bb7127e5e004b41ce433c627799cee5ab1200c7b805cf5184cda9'
files=json.loads(gzip.decompress(raw));assert set(files)=={'app.js','journey.js','experience.css','index.html'}
backup=run/('backup-'+str(int(time.time())));backup.mkdir(mode=0o700)
for name in files:
 p=root/name; info=p.lstat();assert stat.S_ISREG(info.st_mode) and info.st_uid==os.getuid() and info.st_nlink==1
 (backup/name).write_bytes(p.read_bytes())
for name in files:
 fd,tmp=tempfile.mkstemp(dir=root,prefix='.polish-')
 with os.fdopen(fd,'w') as f:f.write(files[name]);f.flush();os.fsync(f.fileno())
 os.chmod(tmp,0o644);os.replace(tmp,root/name)
app_id=sys.argv[1];assert re.fullmatch(r'[0-9a-f-]{36}',app_id)
host=os.environ.get('API_URL','').replace('https://','').rstrip('/');assert host=='my.opalstack.com'
req=urllib.request.Request('https://my.opalstack.com/api/v1/app/installed/',data=json.dumps([{'id':app_id}]).encode(),headers={'Authorization':'Token '+os.environ['OPAL_TOKEN'],'Content-Type':'application/json'},method='POST')
with urllib.request.urlopen(req,timeout=20) as r:assert 200<=r.status<300
print('Visual and wording fixes installed')
PYCODE
